graphql.query:
{
  rackCount
  racks(size: 5) {
    name
    heightUnits
    children { name type }
    administrators {
      primaryAdministrator
      person { name personType contact { email endpoint } }
    }
  }
}

query RackOverview($page: Int!, $size: Int!, $nameLike: String) {
  rackCount(nameLike: $nameLike)
  racks(page: $page, size: $size, nameLike: $nameLike) {
    id name serialNumber heightUnits
    children { id type name serialNumber }
    administrators { primaryAdministrator person { id name personType contact { email phone endpoint } } }
  }
}
